test_suite:
test('type-level: MapOptional makes props optional', () => {
  type T = MapOptional<{ x: number; y: string }>;
  type Check = T extends { x?: number; y?: string } ? true : false;
  const check: Check = true;
  expect(check).toBe(true);
});

test('type-level: MapRequired makes props required', () => {
  type T = MapRequired<{ x?: number; y?: string }>;
  type Check = T extends { x: number; y: string } ? true : false;
  const check: Check = true;
  expect(check).toBe(true);
});

test('type-level: MapOptional matches Partial', () => {
  type T = { a: boolean; b: number };
  type Check = MapOptional<T> extends Partial<T> ? true : false;
  const check: Check = true;
  expect(check).toBe(true);
});

test('type-level: MapRequired matches Required', () => {
  type T = { a?: boolean; b?: number };
  type Check = MapRequired<T> extends Required<T> ? true : false;
  const check: Check = true;
  expect(check).toBe(true);
});

// __hidden__
test('type-level: round-trip optional then required', () => {
  type T = { name: string; age: number };
  type Check = MapRequired<MapOptional<T>> extends T ? true : false;
  const check: Check = true;
  expect(check).toBe(true);
});
